    /**
     * Tests getting all InventoryTransactions.
     *
     * @return    Collection
     */
    public List<InventoryTransaction> testGetAll() throws Throwable {
    LOGGER.info( "InventoryTransactionTest:testGetAll() - Retrieving Collection of InventoryTransactions:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InventoryTransaction : " );
    List<InventoryTransaction> collection  = null;

    try {
        // call the static get method on the InventoryTransactionService
        collection = service.getAllInventoryTransaction();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InventoryTransaction currEntity  = null;
            Iterator<InventoryTransaction> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInventoryTransactionId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

